/* Snippet builder: generates Python from the form. No network, no API key. */
(function () {
  'use strict';
  var $ = function (s) { return document.querySelector(s); };
  var out = $('#snippet-output'), status = $('#snippet-status');
  var CHROMS = []; for (var i = 1; i <= 22; i++) CHROMS.push('chr' + i); CHROMS.push('chrX', 'chrY');
  $('#chrom-list').innerHTML = CHROMS.map(function (c) { return '<option value="' + c + '">'; }).join('');
  var SPLICE = ['SPLICE_SITES', 'SPLICE_SITE_USAGE', 'SPLICE_JUNCTIONS'];

  function setErr(id, msg, input) {
    $('#e-' + id).textContent = msg || '';
    if (input) { if (msg) input.setAttribute('aria-invalid', 'true'); else input.removeAttribute('aria-invalid'); }
  }
  function read() {
    var errs = 0, f = {};
    var chrom = $('#f-chrom'), pos = $('#f-pos'), ref = $('#f-ref'), alt = $('#f-alt'), onto = $('#f-onto');
    f.chrom = chrom.value.trim();
    if (/^\d+$/.test(f.chrom) || /^[xy]$/i.test(f.chrom)) f.chrom = 'chr' + f.chrom.toUpperCase();
    if (/^chr[xy]$/i.test(f.chrom)) f.chrom = 'chr' + f.chrom.slice(3).toUpperCase();
    if (CHROMS.indexOf(f.chrom) < 0) { setErr('chrom', 'Use chr1–chr22, chrX or chrY.', chrom); errs++; } else setErr('chrom', '', chrom);
    var p = pos.value.trim();
    if (!/^[1-9]\d*$/.test(p)) { setErr('pos', 'Enter a positive whole number (1-based).', pos); errs++; } else { f.pos = p; setErr('pos', '', pos); }
    [['ref', ref], ['alt', alt]].forEach(function (x) {
      var v = x[1].value.trim().toUpperCase();
      if (!/^[ACGT]+$/.test(v)) { setErr(x[0], 'Only the letters A, C, G, T are allowed.', x[1]); errs++; } else { f[x[0]] = v; setErr(x[0], '', x[1]); }
    });
    var terms = onto.value.split(',').map(function (s) { return s.trim(); }).filter(Boolean);
    var bad = terms.filter(function (t) { return !/^[A-Za-z][A-Za-z0-9_]*:\d+$/.test(t); });
    if (bad.length) { setErr('onto', 'Expected CURIEs like UBERON:0002107 (got "' + bad[0] + '").', onto); errs++; } else setErr('onto', '', onto);
    f.terms = terms;
    f.len = $('#f-len').value;
    f.scorers = Array.prototype.map.call(document.querySelectorAll('#scorers input:checked'), function (c) { return c.value; });
    if (!f.scorers.length) { setErr('scorers', 'Tick at least one scorer.'); errs++; } else setErr('scorers', '');
    f.errs = errs;
    return f;
  }
  var q = function (s) { return "'" + s + "'"; };

  function generate(f) {
    var hasSplice = f.scorers.some(function (s) { return SPLICE.indexOf(s) >= 0; });
    var L = [];
    L.push('# Generated by the AlphaGenome Guide snippet builder (unofficial). Based on guide §6.5 and §6.6.1.');
    L.push('# Set your key first (never hard-code it):  export ALPHA_GENOME_API_KEY="your-key-here"');
    L.push('import pandas as pd');
    L.push('from alphagenome import colab_utils');
    L.push('from alphagenome.data import genome');
    L.push('from alphagenome.models import dna_client, variant_scorers');
    L.push('');
    L.push('# get_api_key() checks the ALPHA_GENOME_API_KEY environment variable first, then Colab secrets.');
    L.push('dna_model = dna_client.create(colab_utils.get_api_key())');
    L.push('');
    L.push("variant = genome.Variant('" + f.chrom + "', " + f.pos + ", '" + f.ref + "', '" + f.alt + "')   # 1-based, hg38");
    L.push('interval = variant.reference_interval.resize(dna_client.' + f.len + ')');
    L.push('');
    L.push('scorers = [variant_scorers.RECOMMENDED_VARIANT_SCORERS[k]');
    L.push('           for k in (' + f.scorers.map(q).join(', ') + (f.scorers.length === 1 ? ',' : '') + ')]');
    L.push('');
    L.push('scores = dna_model.score_variant(interval=interval, variant=variant,');
    L.push('                                 variant_scorers=scorers)');
    L.push('df = variant_scorers.tidy_scores([scores], match_gene_strand=True)');
    if (hasSplice) {
      L.push('');
      L.push('# Merged splicing score (the method used in the paper):');
      L.push('# alphagenome_splicing = max|Δ splice_sites| + max|Δ splice_site_usage| + max|Δ splice_junctions| / 5');
      L.push('def merged_splicing(df: pd.DataFrame) -> pd.DataFrame:');
      L.push('    df = df.copy()');
      L.push("    df['variant_id'] = df['variant_id'].map(str)");
      L.push("    m = (df.groupby(['variant_id', 'output_type'])['raw_score'].max()");
      L.push('           .reset_index()');
      L.push("           .pivot(index='variant_id', columns='output_type', values='raw_score')");
      L.push('           .fillna(0.0))');
      L.push("    m['alphagenome_splicing'] = (m.get('SPLICE_SITES', 0.0)");
      L.push("                                 + m.get('SPLICE_SITE_USAGE', 0.0)");
      L.push("                                 + m.get('SPLICE_JUNCTIONS', 0.0) / 5.0)");
      L.push("    return m.reset_index().sort_values('alphagenome_splicing', ascending=False)");
      L.push('');
      L.push('print(merged_splicing(df))   # > 1.0 generally indicates a large effect; calibrate on your gene (guide §6.6.1)');
    }
    if (f.terms.length) {
      L.push('');
      L.push('# Keep only the requested cell types / tissues (filter ontology_curie in the tidy table).');
      L.push('ontology_terms = [' + f.terms.map(q).join(', ') + ']');
      L.push("df = df[df['ontology_curie'].isin(ontology_terms)]");
    }
    L.push('');
    L.push('# Strongest effects (quantile_score is calibrated against background variants)');
    L.push("col = 'quantile_score' if 'quantile_score' in df else 'raw_score'");
    L.push('top = (df.assign(abs_q=df[col].abs())');
    L.push("         .sort_values('abs_q', ascending=False)");
    L.push("         [['output_type', 'gene_name', 'biosample_name', 'track_name',");
    L.push("           'raw_score', col]].head(20))");
    L.push('print(top)');
    L.push("df.to_csv('variant_scores.csv', index=False)");
    return L.join('\n');
  }
  function update() {
    var f = read();
    if (f.errs) {
      out.textContent = '# Fix the highlighted fields to generate code.';
      status.textContent = f.errs + ' field' + (f.errs > 1 ? 's need' : ' needs') + ' attention.';
      return;
    }
    out.textContent = generate(f);
    status.textContent = '';
  }
  document.getElementById('builder-form').addEventListener('input', update);
  document.getElementById('builder-form').addEventListener('change', update);
  document.getElementById('builder-form').addEventListener('submit', function (e) { e.preventDefault(); });
  document.querySelectorAll('[data-onto]').forEach(function (b) {
    b.addEventListener('click', function () { $('#f-onto').value = b.getAttribute('data-onto'); update(); });
  });
  $('#copy-snippet').addEventListener('click', function () {
    var f = read();
    if (f.errs) { status.textContent = 'Fix the highlighted fields before copying.'; return; }
    window.agCopy(out.textContent, this);
  });
  // Worked examples (variants from the paper and from guide §6.4/§6.6.1)
  var PRESETS = {
    rs9610445: { chrom: 'chr22', pos: '36201698', ref: 'A', alt: 'C', len: 'SEQUENCE_LENGTH_1MB', onto: 'UBERON:0001157', scorers: ['RNA_SEQ', 'DNASE', 'CHIP_HISTONE'],
      note: 'Known eQTL/sQTL. Expected: ALT (C) lowers expression of the gene; paper variant score -1.52, quantile -1.00. Tissue: transverse colon (as in guide section 6.4).' },
    brca2: { chrom: 'chr13', pos: '32316462', ref: 'T', alt: 'G', len: 'SEQUENCE_LENGTH_1MB', onto: '', scorers: ['SPLICE_SITES', 'SPLICE_SITE_USAGE', 'SPLICE_JUNCTIONS'],
      note: 'BRCA2 variant near a splice site, from guide section 6.6.1. Splice scorers have no tissue filter, so the ontology field is empty.' },
    exonskip: { chrom: 'chr3', pos: '197081044', ref: 'TACTC', alt: 'T', len: 'SEQUENCE_LENGTH_1MB', onto: '', scorers: ['SPLICE_SITES', 'SPLICE_SITE_USAGE', 'SPLICE_JUNCTIONS'],
      note: '4-bp deletion seen to cause exon skipping in tibial artery (GTEx). Expected: lower exon splice-site usage, new junction bypassing the exon.' },
    newjunction: { chrom: 'chr21', pos: '46126238', ref: 'G', alt: 'C', len: 'SEQUENCE_LENGTH_1MB', onto: '', scorers: ['SPLICE_SITES', 'SPLICE_SITE_USAGE', 'SPLICE_JUNCTIONS'],
      note: 'Seen in a GTEx RNA-seq sample as a new splice junction and an extended exon.' },
    tal1: { chrom: 'chr1', pos: '47239296', ref: 'C', alt: 'ACG', len: 'SEQUENCE_LENGTH_1MB', onto: '', scorers: ['RNA_SEQ', 'DNASE', 'CHIP_HISTONE'],
      note: 'Oncogenic T-ALL neo-enhancer near TAL1. The paper used CD34+ common myeloid progenitor (CMP) tracks: find their ontology term with guide section 6.1 and paste it into the tissue field (see G4).' }
  };
  document.querySelectorAll('[data-preset]').forEach(function (b) {
    b.addEventListener('click', function () {
      var p = PRESETS[b.getAttribute('data-preset')];
      $('#f-chrom').value = p.chrom; $('#f-pos').value = p.pos; $('#f-ref').value = p.ref; $('#f-alt').value = p.alt;
      $('#f-len').value = p.len; $('#f-onto').value = p.onto;
      document.querySelectorAll('#scorers input').forEach(function (c) { c.checked = p.scorers.indexOf(c.value) >= 0; });
      $('#preset-note').textContent = p.note;
      update();
    });
  });
  update();
})();
